"use client";

import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from "recharts";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { MeterWithReading } from "@/lib/types";

function barColor(meter: MeterWithReading) {
  const power = meter.latestReading?.powerKw ?? 0;
  if (meter.maxPowerKw) {
    const pct = (power / meter.maxPowerKw) * 100;
    if (pct >= 96) return "var(--accent-red)";
    if (pct >= 87) return "var(--accent-amber)";
  }
  return "var(--accent-green)";
}

export function EquipmentPowerChart({ meters }: { meters: MeterWithReading[] }) {
  const data = meters
    .filter((m) => m.latestReading)
    .map((m) => ({ name: m.name, kw: m.latestReading!.powerKw, color: barColor(m) }));

  return (
    <Card>
      <CardHeader>
        <CardTitle className="font-display text-[13px] text-muted-foreground">Equipment-wise Power Consumption</CardTitle>
        <p className="text-xs text-muted-foreground">Actual kW · live</p>
      </CardHeader>
      <CardContent>
        {data.length === 0 ? (
          <div className="flex h-56 items-center justify-center text-sm text-muted-foreground">No meter data available</div>
        ) : (
          <ResponsiveContainer width="100%" height={220}>
            <BarChart data={data}>
              <CartesianGrid strokeDasharray="3 3" className="stroke-muted" />
              <XAxis dataKey="name" tick={{ fontSize: 10 }} interval={0} angle={-20} textAnchor="end" height={50} />
              <YAxis tick={{ fontSize: 11 }} unit=" kW" />
              <Tooltip formatter={(value: any, name: any, props: any) => [value ? `${value} kW` : "N/A", "Power"]} />
              <Bar dataKey="kw" radius={[4, 4, 0, 0]}>
                {data.map((d, i) => (
                  <Cell key={i} fill={d.color} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        )}
      </CardContent>
    </Card>
  );
}

import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { MeterWithReading } from "@/lib/types";

interface MeterDemandCardsProps {
  meters: MeterWithReading[];
  monthlyPeaks: Record<number, number>;
}

function severity(pct: number) {
  if (pct >= 96) return { label: "Alert", border: "border-t-[var(--accent-red)]", badge: "bg-[var(--accent-red)]/15 text-[var(--accent-red)]" };
  if (pct >= 87) return { label: "Alarm", border: "border-t-[var(--accent-amber)]", badge: "bg-[var(--accent-amber)]/15 text-[var(--accent-amber)]" };
  return { label: "Normal", border: "border-t-[var(--accent-green)]", badge: "bg-[var(--accent-green)]/15 text-[var(--accent-green)]" };
}

export function MeterDemandCards({ meters, monthlyPeaks }: MeterDemandCardsProps) {
  if (meters.length === 0) {
    return <p className="text-sm text-muted-foreground">No meters have thresholds configured yet</p>;
  }

  return (
    <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
      {meters.map((meter) => {
        const power = meter.latestReading?.powerKw ?? 0;
        const max = meter.maxPowerKw ?? 1;
        const pct = (power / max) * 100;
        const sev = severity(pct);
        const peak = monthlyPeaks[meter.id] ?? power;

        return (
          <div key={meter.id} className={cn("rounded-lg border border-t-2 bg-card p-4", sev.border)}>
            <div className="flex items-center justify-between">
              <span className="font-display text-[13px]">
                {meter.name} <span className="text-muted-foreground">({meter.location || "—"})</span>
              </span>
              <Badge className={sev.badge}>{sev.label}</Badge>
            </div>
            <div className="mt-3 grid grid-cols-3 gap-3 text-center">
              <div>
                <p className="font-display text-[9.5px] text-muted-foreground">Current Demand</p>
                <p className="font-mono-ems text-base font-semibold text-[var(--accent-cyan)]">
                  {power.toFixed(0)} <span className="text-[9.5px] text-muted-foreground">kW</span>
                </p>
              </div>
              <div>
                <p className="font-display text-[9.5px] text-muted-foreground">Loading</p>
                <p className="font-mono-ems text-base font-semibold text-[var(--accent-cyan)]">
                  {pct.toFixed(1)}<span className="text-[9.5px] text-muted-foreground">%</span>
                </p>
              </div>
              <div>
                <p className="font-display text-[9.5px] text-muted-foreground">Max Demand (Month)</p>
                <p className="font-mono-ems text-base font-semibold text-[var(--accent-cyan)]">
                  {peak.toFixed(0)} <span className="text-[9.5px] text-muted-foreground">kW</span>
                </p>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

files.components/dashboard/meter-form-dialog.t:
"use client";

import { useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { MeterWithReading } from "@/lib/types";
import { meterFormSchema, MeterFormInput, MeterFormValues } from "@/lib/schemas/meter";

interface MeterFormDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  meter?: MeterWithReading | null; // null/undefined = add mode, present = edit mode
  onSuccess: () => void;
}

export function MeterFormDialog({ open, onOpenChange, meter, onSuccess }: MeterFormDialogProps) {
  const isEdit = Boolean(meter);

  const {
  register,
  handleSubmit,
  reset,
  setValue,
  watch,
  formState: { errors, isSubmitting },
} = useForm<MeterFormInput, any, MeterFormValues>({
  resolver: zodResolver(meterFormSchema),
  defaultValues: { name: "", location: "", status: "active", minPowerKw: "", maxPowerKw: "" },
});

async function onSubmit(values: MeterFormValues) {
  // values.minPowerKw / maxPowerKw are already `number | undefined` here — validated output
  const payload = {
    ...values,
    minPowerKw: values.minPowerKw === "" || values.minPowerKw === undefined ? null : values.minPowerKw,
    maxPowerKw: values.maxPowerKw === "" || values.maxPowerKw === undefined ? null : values.maxPowerKw,
  };

  const url = isEdit ? `/api/meters/${meter!.id}` : "/api/meters";
  const method = isEdit ? "PATCH" : "POST";

  const res = await fetch(url, {
    method,
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });

  if (res.ok) {
    onOpenChange(false);
    onSuccess();
  }
}
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{isEdit ? "Edit meter" : "Add meter"}</DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="name">Name</Label>
            <Input id="name" {...register("name")} />
            {errors.name && <p className="text-sm text-destructive">{errors.name.message}</p>}
          </div>

          <div className="space-y-2">
            <Label htmlFor="location">Location</Label>
            <Input id="location" {...register("location")} />
          </div>

          <div className="space-y-2">
            <Label htmlFor="status">Status</Label>
            <Select value={watch("status")} onValueChange={(v) => setValue("status", v as MeterFormValues["status"])}>
              <SelectTrigger id="status">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="active">Active</SelectItem>
                <SelectItem value="offline">Offline</SelectItem>
                <SelectItem value="maintenance">Maintenance</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="minPowerKw">Min power (kW)</Label>
              <Input id="minPowerKw" type="number" step="0.1" {...register("minPowerKw")} />
            </div>
            <div className="space-y-2">
              <Label htmlFor="maxPowerKw">Max power (kW)</Label>
              <Input id="maxPowerKw" type="number" step="0.1" {...register("maxPowerKw")} />
            </div>
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={isSubmitting}>
              {isEdit ? "Save changes" : "Add meter"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

