              <YAxis type="category" dataKey="name" tick={{ fontSize: 11 }} width={100} />
              <Tooltip />
              <Bar dataKey="current" name="Current (kW)" fill="var(--accent-cyan)" radius={[0, 4, 4, 0]} />
