function AlarmsFeed({ alerts }: { alerts: AlertWithMeter[] }) {
  return (
    <div className="space-y-1 max-h-60 overflow-y-auto">
      {alerts.length === 0 && (
        <p className="text-xs text-muted-foreground py-4 text-center">
